const DELETED_TXS_KEY = 'school_saas_deleted_txs';

export const getDeletedTxIds = (): Set<string> => {
  try {
    const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(DELETED_TXS_KEY) : null;
    const localSet: string[] = raw ? JSON.parse(raw) : [];
    const merged = new Set([...KNOWN_DELETED_TX_IDS, ...localSet]);
    return merged;
  } catch {
    return new Set(KNOWN_DELETED_TX_IDS);
  }
};

export const addDeletedTxId = (id: string) => {
  try {
    const set = getDeletedTxIds();
    set.add(id);
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(DELETED_TXS_KEY, JSON.stringify(Array.from(set).slice(-2000)));
    }
  } catch (e) {
    console.error('Error saving deleted tx id:', e);
  }
};

export const isDeletedTx = (id: string): boolean => {
  return getDeletedTxIds().has(id);
};
